\mathbb{E}_c \left[
    1 - \frac{{n - c \choose k}}{{n \choose k}}
  \right]
  &=
  1 -
  \mathbb{E}_c \left[
    \frac{{n - c \choose k}}{{n \choose k}}
  \right]
  \\
  &=
  1
  -
  \sum_{i = 0}^{n - k} {
    \frac{{n - i \choose k}}{{n \choose k}}
    {n \choose i} p^i (1 - p)^{n - i}
  }
  \\
  &=
  1
  -
  \sum_{i = 0}^{n - k} {
    {n - k \choose i} p^i (1 - p)^{n - i}
  }
  \\
  &=
  1
  -
  (1 - p)^k
  \sum_{i = 0}^{n - k} {
    {n - k \choose i} p^i (1 - p)^{n - k - i}
  }
  \\
  &=
  1
  -
  (1 - p)^k.
